  'use strict';

  // Cloud Cargo's state generator is deliberately independent of the renderer.
  function rng(seed) {
    let v = (Number(seed) >>> 0) || 1;
    return function () { v = (v * 1664525 + 1013904223) >>> 0; return v / 4294967296; };
  }
  function shuffle(a, next) {
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(next() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
    return a;
  }
  function sums(cards, allocation, bays) {
    const out = Array.from({ length: bays }, () => ({ mass: 0, energy: 0 }));
    cards.forEach((c, i) => { out[allocation[i]].mass += c.mass; out[allocation[i]].energy += c.energy; });
    return out;
  }
  function countFits(cards, targets, useEnergy) {
    const n = targets.length; let massFits = 0, completeFits = 0;
    const work = Array.from({ length: n }, () => ({ mass: 0, energy: 0 }));
    function walk(i) {
      if (i === cards.length) {
        let massOK = true, energyOK = true;
        for (let b = 0; b < n; b++) {
          if (work[b].mass !== targets[b].mass) massOK = false;
          if (useEnergy && work[b].energy !== targets[b].energy) energyOK = false;
        }
        if (massOK) massFits++;
        if (massOK && energyOK) completeFits++;
        return;
      }
      for (let b = 0; b < n; b++) {
        work[b].mass += cards[i].mass; work[b].energy += cards[i].energy;
        walk(i + 1);
        work[b].mass -= cards[i].mass; work[b].energy -= cards[i].energy;
      }
    }
    walk(0);
    return { massFits, completeFits };
  }
  function makeBoard(seed, stage) {
    const count = 4 + stage, bayCount = stage === 0 ? 2 : 3;
    const next = rng((seed >>> 0) ^ Math.imul(stage + 17, 2654435761));
    for (let attempt = 0; attempt < 80; attempt++) {
      const cards = [];
      for (let i = 0; i < count; i++) cards.push({ mass: 1 + Math.floor(next() * 5), energy: stage ? Math.floor(next() * 4) : 0, bay: -1 });
      const allocation = [];
      for (let i = 0; i < count; i++) allocation.push(i < bayCount ? i : Math.floor(next() * bayCount));
      shuffle(allocation, next);
      const targetSums = sums(cards, allocation, bayCount);
      if (targetSums.some(t => t.mass === 0)) continue;
      if (stage === 2) {
        const test = countFits(cards, targetSums, true);
        if (!(test.completeFits > 0 && test.massFits > test.completeFits)) continue;
      }
      shuffle(cards, next);
      shuffle(targetSums, next);
      return { cards, bays: targetSums.map(t => ({ mass: t.mass, energy: stage ? t.energy : null })) };
    }
    // Deterministic general fallback: duplicate mass cargo makes energy planning material at stage 2.
    const patterns = [
      [{ mass: 1, energy: 0 }, { mass: 2, energy: 0 }, { mass: 3, energy: 0 }, { mass: 4, energy: 0 }],
      [{ mass: 1, energy: 0 }, { mass: 2, energy: 2 }, { mass: 3, energy: 1 }, { mass: 4, energy: 3 }, { mass: 2, energy: 1 }],
      [{ mass: 2, energy: 0 }, { mass: 2, energy: 3 }, { mass: 3, energy: 1 }, { mass: 3, energy: 2 }, { mass: 1, energy: 1 }, { mass: 1, energy: 2 }]
    ];
    const cards = patterns[stage].map(c => ({ mass: c.mass, energy: c.energy, bay: -1 }));
    const alloc = stage === 0 ? [0, 0, 1, 1] : stage === 1 ? [0, 0, 1, 1, 2] : [0, 1, 0, 1, 2, 2];
    return { cards, bays: sums(cards, alloc, bayCount).map(t => ({ mass: t.mass, energy: stage ? t.energy : null })) };
  }
  function installBoard(state) {
    const board = makeBoard(state.seed, state.stage);
    state.cards = board.cards;
    state.bays = board.bays;
    state.selectedCard = 0;
    state.focus = 0;
    state.validation = 0;
    state.dispatchHold = 0;
    state.feedback = 'MANIFEST READY';
  }
  function bayTotal(state, index) {
    let mass = 0, energy = 0;
    state.cards.forEach(c => { if (c.bay === index) { mass += c.mass; energy += c.energy; } });
    return { mass, energy };
  }
  function exact(state) {
    if (!state.cards.length || state.cards.some(c => c.bay < 0)) return false;
    for (let i = 0; i < state.bays.length; i++) {
      const total = bayTotal(state, i), target = state.bays[i];
      if (total.mass !== target.mass || (target.energy !== null && total.energy !== target.energy)) return false;
    }
    return true;
  }
  function activate(state, index) {
    if (state.stage >= 3) return;
    if (index < state.cards.length) {
      state.selectedCard = index;
      state.feedback = 'CRATE ' + (index + 1) + ' SELECTED';
      state.interactions++;
      return;
    }
    const bay = index - state.cards.length;
    if (bay >= 0 && bay < state.bays.length && state.selectedCard >= 0) {
      const card = state.cards[state.selectedCard];
      if (card.bay !== bay) { card.bay = bay; state.assignments++; state.interactions++; state.feedback = 'CRATE ASSIGNED TO BAY ' + String.fromCharCode(65 + bay); }
      else state.feedback = 'ALREADY IN BAY ' + String.fromCharCode(65 + bay);
      state.validation = 0;
    }
  }
  function pointerIndex(state, p) {
    if (!p || p.x < 0 || p.x > 1 || p.y < 0 || p.y > 1) return -1;
    if (p.y >= .08 && p.y <= .39) return state.cards.length + Math.min(state.bays.length - 1, Math.floor(p.x * state.bays.length));
    if (p.y >= .43 && p.y <= .92) {
      const col = Math.min(2, Math.floor(p.x * 3)), row = p.y < .675 ? 0 : 1, i = row * 3 + col;
      return i < state.cards.length ? i : -1;
    }
    return -1;
  }
  const core = {
    create(seed) {
      const state = { seed: Number(seed) >>> 0, tick: 0, stage: 0, score: 0, assignments: 0, interactions: 0, focus: 0, selectedCard: 0, cards: [], bays: [], validation: 0, dispatchHold: 0, moveCooldown: 0, feedback: 'READY TO LOAD', outcome: '' };
      installBoard(state);
      return state;
    },
    step(state, input) {
      if (state.outcome) { state.tick++; return; }
      state.tick++;
      if (state.moveCooldown > 0) state.moveCooldown--;
      if (input && input.action) {
        const hit = pointerIndex(state, input.pointer);
        if (hit >= 0) { state.focus = hit; activate(state, hit); }
        else activate(state, state.focus);
      } else if (input && input.x && state.moveCooldown === 0) {
        const len = state.cards.length + state.bays.length;
        state.focus = (state.focus + (input.x > 0 ? 1 : -1) + len) % len;
        state.moveCooldown = 8;
      }
      if (state.stage < 3 && exact(state)) {
        state.validation++;
        if (state.validation === 1) state.feedback = 'CHECKING MANIFEST…';
        if (state.validation >= 32) {
          state.dispatchHold++;
          if (state.dispatchHold === 1) {
            state.stage++;
            const bonus = Math.max(0, Math.floor((3000 - state.tick) / 30));
            state.score += 250 + bonus + Math.max(0, 18 - state.assignments);
            state.feedback = state.stage === 3 ? 'FLEET DEPARTING!' : 'AIRSHIP DISPATCHED!';
          }
          if (state.stage < 3 && state.dispatchHold >= 72) installBoard(state);
        }
      } else { state.validation = 0; state.dispatchHold = 0; }
      if (state.stage >= 3 && state.tick >= 900) state.outcome = 'complete';
      else if (state.tick >= 3000) { state.outcome = 'incomplete'; state.feedback = 'SHIFT ENDED'; }
    },
    observe(state) { return { tick: state.tick, score: state.score, progress: Math.min(100, Math.floor(state.tick / 30)), interactions: state.interactions, entities: state.cards.length + state.bays.length + 3 }; },
    terminal(state) { return !!state.outcome; }
  };
  window.CloudCargoCore = core;
})();
