  'use strict';
  const shell = document.querySelector('[data-cargo-shell]');
  const goal = document.querySelector('[data-cargo-goal-progress]');
  const best = document.querySelector('[data-cargo-best]');
  const result = document.querySelector('[data-cargo-result]');
  const detail = document.querySelector('[data-cargo-result-detail]');
  let reduced = false;
  let media;
  function setReduced(value) { reduced = !!value; shell.dataset.reducedMotion = String(reduced); }
  function update(snapshot) {
    const s = snapshot.state || {};
    const launched = Math.min(3, s.stage || 0);
    goal.textContent = launched + '/3';
    best.textContent = String(Number.isFinite(snapshot.best) ? snapshot.best : 0);
    const done = s.outcome;
    result.hidden = !done;
    if (done) {
      result.textContent = done === 'complete' ? 'SKYPORT COMPLETE' : 'CARGO INCOMPLETE';
      detail.textContent = done === 'complete'
        ? '3/3 dispatched • ' + s.assignments + ' cargo assignments • score ' + s.score + ' • fleet cleared the clouds.'
        : launched + '/3 dispatched • ' + s.assignments + ' cargo assignments • score ' + s.score + '. Retry: balance every bay’s listed totals.';
    }
  }
  window.CargoPresentation = { snapshot() { return { reducedMotion: reduced, particles: 0, activeVoices: 0 }; } };
  async function boot() {
    media = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(media.matches);
    media.addEventListener('change', e => setReduced(e.matches));
    const metadata = await fetch('./manifest.json').then(r => r.json());
    const canvas = document.querySelector('[data-game-canvas]');
    PlayJoltGameKit.create({
      core: window.CloudCargoCore,
      canvas,
      metadata,
      draw(snapshot, size) {
        update(snapshot);
        const cloned = JSON.parse(JSON.stringify(snapshot));
        window.CloudCargoView.draw(canvas.getContext('2d'), cloned, { width: size.width, height: size.height, reducedMotion: reduced });
      }
    });
  }
  boot().catch(err => { const node = document.querySelector('[data-game-error]'); node.hidden = false; node.textContent = 'Unable to open cargo desk: ' + err.message; });
})();
