    const cards = s.cards || [], bays = s.bays || [], selected = s.selectedCard;
    bays.forEach((bay, i) => {
      const x = sx(i / bays.length + .025), bw = sx(1 / bays.length - .05), y = sy(.08), bh = sy(.31), total = { mass: 0, energy: 0 };
      cards.forEach(c => { if (c.bay === i) { total.mass += c.mass; total.energy += c.energy; } });
      const focused = s.focus === cards.length + i;
      ctx.fillStyle = focused ? '#f07d5a' : '#d9f0ed'; rr(ctx, x, y, bw, bh, 12); ctx.fill();
      ctx.fillStyle = '#53cdbc'; ctx.beginPath(); ctx.ellipse(x + bw / 2, y + bh * .27, bw * .31, bh * .105, 0, 0, Math.PI * 2); ctx.fill();
