      text(ctx, 'BAY ' + String.fromCharCode(65 + i), x + bw / 2, y + bh * .59, Math.max(12, w * .026), '#14243a');
      text(ctx, 'M ' + total.mass + ' / ' + bay.mass, x + bw / 2, y + bh * .73, Math.max(12, w * .026), total.mass === bay.mass ? '#148b78' : '#253b51');
      if (bay.energy !== null) text(ctx, 'E ' + total.energy + ' / ' + bay.energy, x + bw / 2, y + bh * .88, Math.max(12, w * .026), total.energy === bay.energy ? '#148b78' : '#253b51');
    });
    for (let slot = 0; slot < 6; slot++) {
      const col = slot % 3, row = Math.floor(slot / 3), x = sx(col / 3 + .025), y = sy(.43 + row * .25), cw = sx(1 / 3 - .05), ch = sy(.20);
      if (slot >= cards.length) { ctx.strokeStyle = '#7090a0'; ctx.globalAlpha = .35; rr(ctx, x, y, cw, ch, 10); ctx.stroke(); ctx.globalAlpha = 1; continue; }
