      ctx.fillStyle = hot ? '#f28b64' : '#f1dfb8'; rr(ctx, x, y, cw, ch, 10); ctx.fill();
      ctx.strokeStyle = hot ? '#fff2c8' : '#b69263'; ctx.lineWidth = 2; ctx.stroke();
      text(ctx, 'CRATE ' + (slot + 1), x + cw / 2, y + ch * .25, Math.max(12, w * .026), '#29253a');
      text(ctx, 'MASS ' + c.mass, x + cw / 2, y + ch * .51, Math.max(12, w * .025), '#29253a');
      text(ctx, 'ENERGY ' + c.energy, x + cw / 2, y + ch * .73, Math.max(12, w * .025), '#29253a');
